'use strict';
const BerrabaiCore=(()=>{
 const day=d=>{const t=new Date(d);return `${t.getFullYear()}-${String(t.getMonth()+1).padStart(2,'0')}-${String(t.getDate()).padStart(2,'0')}`};
 const shift=(s,n)=>{const d=new Date(s+'T12:00:00');d.setDate(d.getDate()+n);return day(d)};
 const paidStatuses=new Set(['已支付','已付款','待发货','已发货','已完成','交易成功','部分退款','已退款','退款成功']);
 const isPaidStatus=status=>paidStatuses.has(status);
 const comparison=(n,p,has,days)=>!has?'无上期数据':p===0?'上期为 0，暂不计算增幅':`${n>=p?'增长':'下降'} ${Math.abs((n-p)/p*100).toFixed(1)}% · 比前${days}天`;
 function reportRange(kind,today,start,end){if(kind==='day')return [shift(today,-1),shift(today,-1)];if(kind==='week')return [shift(today,-7),shift(today,-1)];return [start,end]}
 function summarize(orders,start,end){if(![start,end].every(x=>/^\d{4}-\d{2}-\d{2}$/.test(x)&&!isNaN(new Date(x+'T12:00:00'))&&day(new Date(x+'T12:00:00'))===x))throw Error('请选择有效的开始与结束日期');const n=Math.round((new Date(end+'T12:00:00')-new Date(start+'T12:00:00'))/86400000)+1;if(n<1||n>366)throw Error('请选择1–366天的时间范围');const accepted=o=>isPaidStatus(o.status);const current=orders.filter(o=>o.date>=start&&o.date<=end&&accepted(o));const previous=orders.filter(o=>o.date>=shift(start,-n)&&o.date<start&&accepted(o));const stats=rows=>({revenue:rows.reduce((s,o)=>s+o.paid-o.refund,0),paid:rows.reduce((s,o)=>s+o.paid,0),refund:rows.reduce((s,o)=>s+o.refund,0),quantity:rows.reduce((s,o)=>s+o.qty-o.refundQty,0),orders:new Set(rows.map(o=>o.orderId)).size,lines:rows.length});const group=(field)=>{const m=new Map;current.forEach(o=>{const key=o[field]||'未填写';let r=m.get(key)||{name:key,quantity:0,revenue:0,lines:0};r.quantity+=o.qty-o.refundQty;r.revenue+=o.paid-o.refund;r.lines++;m.set(key,r)});return [...m.values()].sort((a,b)=>b.quantity-a.quantity||b.revenue-a.revenue)};const daily=[];for(let d=start;d<=end;d=shift(d,1))daily.push({date:d,...stats(current.filter(o=>o.date===d))});return {start,end,days:n,...stats(current),previous:stats(previous),products:group('product'),colors:group('color'),daily,coverage:current.length,unrecognizedStatus:orders.filter(o=>o.date>=start&&o.date<=end&&!accepted(o)&&!['已取消','未付款','已关闭'].includes(o.status)).length,unknownColor:current.filter(o=>!o.color||o.color==='未填写').length}}
 function parseCSV(text){text=text.replace(/^\uFEFF/,'');const delim=text.split(/\r?\n/)[0].includes('\t')?'\t':',';let rows=[],row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else if(!quoted&&cell.length)throw Error('CSV引号格式不正确');else quoted=!quoted}else if(c===delim&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell=''}else cell+=c}if(quoted)throw Error('CSV引号未闭合');row.push(cell);if(row.some(x=>x.trim()))rows.push(row);if(rows.length<2)throw Error('文件至少需要表头和一行数据');const headers=rows.shift().map(x=>x.trim());if(new Set(headers).size!==headers.length)throw Error('存在重复列名，请先修改表头');return {headers,rows}}
 const cents=s=>{const v=String(s||'0').trim().replace(/[¥￥,\s]/g,'');if(!/^\d+(\.\d{1,2})?$/.test(v))throw Error('金额需为非负数，最多两位小数');const [a,b='']=v.split('.');const x=Number(a)*100+Number(b.padEnd(2,'0'));if(!Number.isSafeInteger(x)||x>1e11)throw Error('金额超出范围');return x};
 function normalize(raw,mapping){return raw.rows.map((r,i)=>{const val=k=>mapping[k]===undefined||mapping[k]===''?'':String(r[Number(mapping[k])]||'').trim();let date=val('date').slice(0,10).replace(/[/.]/g,'-');if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||isNaN(new Date(date+'T12:00:00'))||day(new Date(date+'T12:00:00'))!==date)throw Error(`第${i+2}行：日期需为YYYY-MM-DD`);const orderId=val('orderId'),lineId=val('lineId'),product=val('product');if(!orderId||!product)throw Error(`第${i+2}行：订单号和商品名不能为空`);const qty=Number(val('qty')),refundQty=Number(val('refundQty')||0);if(!Number.isInteger(qty)||qty<1||qty>100000||!Number.isInteger(refundQty)||refundQty<0||refundQty>qty)throw Error(`第${i+2}行：数量或退货件数无效`);let paid,refund;try{paid=cents(val('paid'));refund=cents(val('refund'))}catch(e){throw Error(`第${i+2}行：${e.message}`)}if(refund>paid)throw Error(`第${i+2}行：退款不能超过实付金额`);const color=val('color')||'未填写';return {id:JSON.stringify([orderId,lineId||product+'|'+color]),orderId,lineId,date,product,color,qty,refundQty,paid,refund,status:val('status')||'待核对'}})}
 return {day,shift,summarize,parseCSV,normalize,cents,isPaidStatus,comparison,reportRange};
})();
if(typeof window!=='undefined')window.BerrabaiCore=BerrabaiCore;
if(typeof document!=='undefined')(()=>{
const publicDemo=window.BERRABAI_PUBLIC_DEMO===true,storageKey=publicDemo?'bb-public-demo-v1':'bb-owner-v1';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),C=BerrabaiCore,today=C.day(new Date),emptyState=()=>({orders:[],events:[],intel:[],reports:[],tasks:[],feeds:[]});
let state=emptyState(),realState=emptyState(),version=0,view='overview',demo=false,preview=location.protocol==='file:'||publicDemo,auth=false,busy=false,reportId='',productTab='sales',search='',intelFilter='全部',period=7,start=C.shift(today,-6),end=today;
const catalog=window.BERRABAI_CATALOG||[];const money=n=>'¥'+(n/100).toLocaleString('zh-CN',{minimumFractionDigits:0,maximumFractionDigits:2}),uid=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,8),stamp=()=>new Date().toLocaleString('zh-CN');let toastTimer,saveError='';
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4500)}
function modal(title,html){$('#modalTitle').textContent=title;$('#modalBody').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
function close(){$('#modal').close()}
async function api(path,data){if(publicDemo)throw Error('公开演示不连接业务服务器。');const r=await fetch('/api/'+path,{credentials:'same-origin',method:data===undefined?'GET':'POST',headers:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)});let x;try{x=await r.json()}catch{throw Error('服务未更新，请重启本地服务后刷新页面')}if(!r.ok){if(r.status===401){auth=false;login()}throw Error(x.error||'请求失败')}return x}
async function persist(){if(demo)return;if(preview){localStorage.setItem(storageKey,JSON.stringify(state));realState=structuredClone(state);return}const x=await api('business/state',{version,state});version=x.version;realState=structuredClone(state)}
async function change(fn){if(busy)return;busy=true;const old=structuredClone(state);try{saveError='';fn();await persist();render();return true}catch(e){state=old;saveError=e.message;toast(e.message);render();return false}finally{busy=false}}
function download(name,body,type='text/plain;charset=utf-8'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([body],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function sample(){const s=emptyState();const specs=[['沙滩小憩（蝴蝶结款）','粉色',528],['沙滩小憩（高配紫）','紫色',618],['星星人幸运马','黄色',388],['海豚melody','粉色',218],['玲娜贝儿手机支架','粉色',238]];for(let d=13;d>=0;d--){for(let j=0;j<(d<7?4:2);j++){const p=specs[(d+j)%specs.length],ref=d===2&&j===0;s.orders.push({id:'sample-'+d+'-'+j,orderId:'示例'+d+j,lineId:'1',date:C.shift(today,-d),product:p[0],color:p[1],qty:1,refundQty:ref?1:0,paid:p[2]*100,refund:ref?p[2]*100:0,status:'已支付'})}}s.events=[{id:uid(),date:C.shift(today,-3),title:'示例：发布紫色款实拍内容',type:'内容发布',note:'仅为演示记录，不代表真实经营事件'}];s.tasks=[{id:uid(),title:'核对本周热销款的材料与交期',due:C.shift(today,2),done:false},{id:uid(),title:'补充商品颜色字段，减少未知数据',due:C.shift(today,1),done:false}];return s}
function metrics(){return C.summarize(state.orders,start,end)}
const compare=(n,p,has,days=period)=>C.comparison(n,p,has,days);
function header(title,en,sub,filters=true){return `<div class="page-head"><div><div class="eyebrow">${en}</div><h1>${title}</h1><p class="sub">${sub}</p></div>${filters?`<div><div class="filters">${[1,7,30].map(n=>`<button data-period="${n}" class="${period===n?'active':''}">${n===1?'今天':'近'+n+'天'}</button>`).join('')}</div><div class="date-range" style="margin-top:9px"><input id="rangeStart" aria-label="开始日期" type="date" value="${start}"><span>至</span><input id="rangeEnd" aria-label="结束日期" type="date" value="${end}"><button class="mini-link" data-action="range">应用</button></div></div>`:''}</div>`}
const empty=(title,text)=>`<div class="empty"><strong>${title}</strong>${text}</div>`;
function rankings(items,limit=4){const top=items.slice(0,limit),max=Math.max(1,...top.map(x=>x.quantity));return top.map(x=>`<div class="rank"><div class="rank-top"><span>${E(x.name)}</span><span>${x.quantity} 件</span></div><div class="track"><span style="width:${x.quantity/max*100}%"></span></div></div>`).join('')}
function productTable(m){return `<div class="table-wrap"><table><thead><tr><th>款式</th><th>净销量</th><th>净实收</th><th>明细数</th></tr></thead><tbody>${m.products.filter(x=>x.name.toLowerCase().includes(search.toLowerCase())).map(x=>`<tr><td>${E(x.name)}</td><td>${x.quantity}</td><td>${money(x.revenue)}</td><td>${x.lines}</td></tr>`).join('')}</tbody></table></div>`}
function overview(){const m=metrics(),hero=m.coverage?`${E(m.products[0]?.name||'暂无')}，是这段时间的销量领先款。`:'把灵感，变成有依据的决定。';return header('你好，莓莓兔主理人','THE LITTLE BUSINESS ROOM','从商品表现到市场线索，慢慢看清每一次变化。')+`${m.unrecognizedStatus?`<div class="callout" role="status">本期 ${m.unrecognizedStatus} 条明细的订单状态缺失或未识别，已排除统计，请核对来源文件。</div>`:''}<div class="hero"><div><div class="eyebrow">A LITTLE CLARITY, EVERY DAY</div><h2>${hero}</h2><p>${m.coverage?`本期有 ${m.orders} 个支付订单，净销量 ${m.quantity} 件。报告会把数据观察、待验证原因和下一步行动分开呈现。`:'先导入一份订单，看看哪个款式与颜色更受欢迎；也可以查看演示，熟悉你的经营工作台。'}</p><button class="solid" data-action="${m.coverage?'report':'import'}">${m.coverage?'生成这段时间的报告':'导入第一份订单'}</button></div><div class="hero-art" aria-hidden="true">୨୧</div></div><div class="metrics">${[['净实收',money(m.revenue),compare(m.revenue,m.previous.revenue,m.previous.lines),'✧'],['净销量',m.quantity+' 件',compare(m.quantity,m.previous.quantity,m.previous.lines),'✿'],['支付订单',m.orders+' 单','包含后续退款的已支付订单','▤'],['退款金额',money(m.refund),'按下单日期归属，不是当天现金流','↺']].map(([a,b,c,d])=>`<div class="metric"><div class="name">${a}<span>${d}</span></div><strong>${m.coverage?b:'—'}</strong><small>${m.coverage?c:'导入订单后计算'}</small></div>`).join('')}</div><div class="columns"><section class="panel"><div class="panel-head"><h2>销售的节奏</h2><small>${start} 至 ${end} · 净销量</small></div>${m.coverage?chart(m):empty('你的第一条曲线，还在等数据','导入 CSV 订单后，按日期展示实际商品销量。')}<div class="legend"><span><i></i>数量扣除明确记录的退货件数</span></div></section><section class="panel"><div class="panel-head"><h2>大家偏爱什么颜色</h2><button class="mini-link" data-view="products">查看分析</button></div>${m.coverage?rankings(m.colors):empty('颜色偏好尚待发现','订单中的颜色字段会用于分析，不从商品图片猜测。')}<p class="note">${m.unknownColor?'有 '+m.unknownColor+' 条明细未填写颜色；该部分单独列示。':'颜色偏好只反映已导入订单，不代表全网热度。'}</p></section></div><div class="columns"><section class="panel"><div class="panel-head"><h2>款式排行榜</h2><button class="mini-link" data-view="products">全部款式</button></div>${m.coverage?productTable({...m,products:m.products.slice(0,5)}):empty('先认识你的畅销款','统计订单中实际成交的款式，不把咨询量当销量。')}</section><section class="panel"><div class="panel-head"><h2>值得留意的线索</h2><button class="mini-link" data-view="intel">打开情报台</button></div>${intelCards(state.intel.slice(0,2))}<div class="callout">${state.events.length?'已记录 '+state.events.length+' 个经营事件，可在报告中对照观察。':'记录上新、活动、内容发布或缺货，帮助解释变化。'}</div><button class="mini-link" data-action="event">记录一次经营事件</button></section></div><section class="panel"><div class="panel-head"><h2>${preview||demo?'规则报告预览':'AI 经营问答'}</h2><span class="badge">${preview||demo?'无需模型':'基于当前时间范围'}</span></div>${preview||demo?'<p class="sub">这里展示按订单计算的固定格式报告。自由提问需启动本地服务并连接模型。</p><button class="soft" data-action="preview-report" style="margin-top:14px">查看当前范围的规则报告</button>':'<form id="askForm" class="row"><input class="search" id="askInput" style="flex:1;min-width:200px" required maxlength="600" placeholder="例如：这周应该优先关注哪些款式？"><button class="solid" id="askButton">分析一下</button></form>'}<div id="aiAnswer" class="ai-answer" role="status"></div></section>`}
function chart(m){const max=Math.max(1,...m.daily.map(x=>x.quantity));return `<div class="chart">${m.daily.map(x=>`<div class="bar-col" title="${x.date}：${x.quantity}件 / ${money(x.revenue)}"><div class="bar" style="height:${Math.max(1,x.quantity/max*145)}px"></div></div>`).join('')}</div><div class="chart-labels">${m.daily.map((x,i)=>`<span>${m.days>10&&i%Math.ceil(m.days/7)!==0?'':x.date.slice(5)}</span>`).join('')}</div>`}
function products(){const m=metrics();return header('商品与颜色','PRODUCT OBSERVATORY','把销量、配色与商品资料放在一起看。')+`<div class="tab-row"><button data-tab="sales" class="${productTab==='sales'?'active':''}">销售表现</button><button data-tab="catalog" class="${productTab==='catalog'?'active':''}">商品目录 · ${catalog.length} 款</button></div><div class="panel"><div class="stats-caption"><h2 style="margin:0">${productTab==='sales'?'款式销量与净实收':'已整理的小程序商品'}</h2><input class="search" id="productSearch" placeholder="搜索款式或品类" value="${E(search)}" aria-label="搜索商品"></div>${productTab==='sales'?(m.coverage?productTable(m):empty('这个时间范围还没有订单','导入数据后，可以比较款式销量和净实收。')):`<p class="note">目录来自 2026-11-23 小程序列表。金额为当时起价，可能对应寄改；不代表含娃价格、实时库存或市场热度。</p><div class="catalog-grid">${catalog.filter(p=>(p['商品名称']+p['品类']).toLowerCase().includes(search.toLowerCase())).map(p=>`<article class="product-card"><span class="badge">${E(p['品类'])}</span><h3>${E(p['商品名称'])}</h3><strong>¥${E(p['列表起价（元）'])} 起</strong><p>${E(p['页面备注']||'具体规格与最终价格需确认')}</p></article>`).join('')||empty('没有找到款式','换个关键词试试。')}</div>`}</div>${productTab==='sales'?`<div class="columns" style="margin-top:20px"><div class="panel"><h2>颜色偏好</h2>${m.coverage?rankings(m.colors,10):empty('暂无颜色数据','导入时可映射颜色列。')}</div><div class="panel"><h2>分析口径</h2><p class="sub">净实收＝明细实付金额－退款金额。净销量＝购买数量－明确记录的退货件数。仅已识别的支付、履约及退款状态参与统计；空白、未知和未支付状态排除。退款按原订单日期归属。</p><div class="callout">若只有退款金额，没有退货件数，无法准确扣减销量。请在导入时补充退货件数。</div><p class="sub">上期是紧邻所选范围的相同天数。未记录数据的日期不代表店铺实际没有成交。</p></div></div>`:''}`}
function validUrl(u){try{const x=new URL(u);return ['https:','http:'].includes(x.protocol)?x.href:''}catch{return ''}}
function intelCards(items){return items.length?items.map(x=>`<article class="insight"><span class="badge ${x.status==='已核实'?'green':'amber'}">${E(x.status||'待核实')}</span> <span class="badge">${E(x.kind||'市场线索')}</span><h3>${E(x.title)}</h3><p>${E(x.note||'还没有补充分析。')}</p><p>${E(x.source)} · ${E(x.date||'日期待确认')}</p>${validUrl(x.url)?`<a href="${E(validUrl(x.url))}" target="_blank" rel="noopener noreferrer">查看原始来源</a>`:''}<div style="margin-top:10px"><button class="mini-link" data-intel-edit="${E(x.id)}">核对 / 编辑</button></div></article>`).join(''):empty('把发现，留在这里','添加来源链接，或配置 RSS 获取公开资讯。没有依据时不会自动认定“爆火”或“明星代言”。')}
function intel(){return header('趋势情报台','SIGNALS, WITH SOURCES','区分新品、合作、个人同款与待核实线索。',false)+`<div class="row" style="margin-bottom:20px"><button class="solid" data-action="intel-new">添加线索</button><button class="outline" data-action="fetch-feeds">获取 RSS 更新</button><button class="soft" data-action="feed">添加 RSS 来源</button><select class="search" id="intelFilter" aria-label="筛选情报">${['全部','待核实','已核实'].map(x=>`<option ${x===intelFilter?'selected':''}>${x}</option>`).join('')}</select></div><div class="columns"><div class="panel"><div class="panel-head"><h2>近期发现</h2><small>${state.intel.length} 条已保存线索</small></div>${intelCards(state.intel.filter(x=>intelFilter==='全部'||x.status===intelFilter))}</div><div><section class="panel"><h2>你的来源清单</h2>${state.feeds.map(f=>`<div class="insight"><h3>${E(f.name)}</h3><button class="mini-link" data-feed-edit="${E(f.id)}">编辑来源</button><p style="overflow-wrap:anywhere">${E(f.url)}</p><small class="sub">${E(f.lastFetch?'最近获取：'+f.lastFetch:'尚未获取')}</small></div>`).join('')||empty('尚未配置来源','添加公开 RSS / Atom 地址后，可手动获取更新。')}<p class="note">RSS 新条目默认“待核实”。标题与讨论次数不等于销量，也不能单独证明明星正式代言。</p></section><section class="panel" style="margin-top:20px"><h2>判断前，先问三件事</h2><p class="sub">是否有原始发布方？<br>发布时间是否足够近？<br>与莓莓兔哪些商品真正有关？</p></section></div></div>`}
function reports(){const r=state.reports.find(x=>x.id===reportId)||state.reports[0];if(r)reportId=r.id;return header('日报与周报','A CLEARER PICTURE','保留数据口径和时间范围，回头也能知道为什么这样判断。',false)+`<div class="row" style="margin-bottom:20px"><button class="solid" data-generate="day">生成昨日经营日报</button><button class="soft" data-generate="week">生成最近完整 7 天周报</button><button class="outline" data-action="report">生成当前范围报告</button></div><div class="callout">报告使用已导入订单；最新成交与退款需要重新导入。当前支持手动生成，尚未启用定时采集或通知。</div><div class="columns"><section class="panel"><div class="panel-head"><h2>${r?E(r.title):'报告预览'}</h2>${r?'<button class="mini-link" data-action="export-report">下载报告</button>':''}</div>${r?`<p class="sub">${E(r.created)} · ${r.sample?'业务演示':'导入订单'}</p><div class="report">${E(r.text)}</div><div class="row" style="margin-top:16px"><button class="outline" data-action="print">打印 / 存为 PDF</button></div>`:empty('你的第一份经营报告','导入订单后，选择日报、周报或自定义时间范围。')}</section><aside class="panel"><h2>报告档案</h2><div class="report-list">${state.reports.map(x=>`<button class="report-item" data-report="${E(x.id)}">${E(x.title)}<small>${E(x.created)}${x.sample?' · 示例':''}</small></button>`).join('')||'<p class="sub">暂无报告</p>'}</div></aside></div>`}
function tasks(){return header('把想法，落成行动','SMALL STEPS, REAL PROGRESS','记录下一步，完成后勾选。',false)+`<section class="panel"><div class="panel-head"><h2>${state.tasks.filter(x=>!x.done).length} 项待办</h2><button class="solid" data-action="task">添加行动</button></div>${state.tasks.map(x=>`<label class="task ${x.done?'done':''}"><input type="checkbox" data-task="${E(x.id)}" ${x.done?'checked':''}><div><p>${E(x.title)}</p><small>${x.due?'截止 '+E(x.due):'未设置截止日期'}</small></div></label>`).join('')||empty('从一个小行动开始','把补货核对、内容实验或资料整理记下来。')}</section><section class="panel" style="margin-top:20px"><div class="panel-head"><h2>经营事件记录</h2><button class="mini-link" data-action="event">记录事件</button></div>${state.events.map(x=>`<div class="insight"><span class="badge">${E(x.type)}</span><h3>${E(x.date)} · ${E(x.title)}</h3><p>${E(x.note)}</p></div>`).join('')||empty('给经营变化留下背景','记录活动、上新、价格调整、内容发布或缺货；报告会作为可能相关的背景列出。')}</section>`}
function settings(){return header('资料与设置','A PLACE FOR EVERYTHING','商品资料、订单和情报，都由你自己掌握。',false)+`<div class="columns"><section class="panel"><h2>订单与数据</h2><p class="sub">已保存 ${state.orders.length} 条订单明细，${state.reports.length} 份报告。${preview?'当前数据保存在此浏览器中。':'登录后数据保存在本机数据库。'}</p><div class="row" style="margin-top:20px"><button class="solid" data-action="import">导入订单</button><button class="outline" data-action="template">下载 CSV 模板</button><button class="soft" data-action="backup">导出备份</button><button class="outline" data-action="restore">恢复备份</button></div><div class="callout">一行代表一条商品明细，金额应为该明细的实付，不能把整个订单总额重复填入多行。订单号与明细编号用于去重。</div><p class="note">同一明细再次导入会更新，因此可以用新导出的订单表同步退款状态。未付款、已取消和已关闭会排除统计。</p></section><section class="panel"><h2>经营助手</h2><p class="sub" id="providerText">${preview?'文件预览可体验统计、报告与记录。连接本地服务后可调用本地模型进行经营分析。':'正在使用服务端配置的模型。'}</p><p class="note">本地模型需要安装并运行 Ollama。没有模型时，订单统计、普通日报周报和行动清单照常可用。联网情报需要独立配置 RSS 来源。</p><button class="outline" data-action="model-help">查看本地模型启动方式</button></section></div><section class="panel"><div class="panel-head"><h2>品牌知识与商品目录</h2><button class="soft" data-tab="catalog" data-view="products">浏览 ${catalog.length} 款商品</button></div><p class="sub">保留已整理的小程序商品资料，用于识别款式。商品列表没有可靠的颜色列，因此订单分析使用你导入的实际颜色字段。</p></section>`}
function render(){const pages={overview,products,intel,reports,tasks,settings};$('#main').innerHTML=(publicDemo?'<div class="demo-note">公开演示：导入、报告和行动记录仅保存在当前浏览器。换设备不会自动同步，可在「资料与设置」导出备份。</div>':'')+(demo?'<div class="demo-note">当前为演示工作台。修改仅在本次预览中保留，点击右上角“返回我的数据”退出。</div>':'')+pages[view]();$$('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#demoButton').textContent=demo?'返回我的数据':'查看演示';$('#modeLabel').textContent=demo?'业务演示':preview?(publicDemo?'在线演示 · 本机保存':'浏览器本地'):'私人工作台';$('#modeLabel').className='badge '+(demo?'amber':'green')}
function go(v){view=v;search='';render();window.scrollTo(0,0)}
function reportText(m){const top=m.products[0],color=m.colors.find(x=>x.name!=='未填写'),events=state.events.filter(x=>x.date>=m.start&&x.date<=m.end),intels=state.intel.filter(x=>x.date>=m.start&&x.date<=m.end);return `莓莓兔经营报告\n${m.start} 至 ${m.end}${demo?' · 业务演示':''}\n\n一、数据观察\n支付订单 ${m.orders} 单；净销量 ${m.quantity} 件。\n实付 ${money(m.paid)}；退款 ${money(m.refund)}；净实收 ${money(m.revenue)}。\n净实收对比：${compare(m.revenue,m.previous.revenue,m.previous.lines,m.days)}。\n比较期：${C.shift(m.start,-m.days)} 至 ${C.shift(m.start,-1)}。\n${top?'销量领先款：'+top.name+'，'+top.quantity+' 件，净实收 '+money(top.revenue)+'。':'无已支付明细，无法判断畅销款。'}\n${color?'已填写颜色中销量最高：'+color.name+'，'+color.quantity+' 件。':'没有可用颜色数据。'}\n\n二、可能相关的背景（尚不能认定因果）\n${events.length?events.map(x=>x.date+' '+x.title+'：'+x.note).join('\n'):'没有记录本期活动、价格或内容变化，暂无法解释原因。'}\n\n三、市场线索\n${intels.length?intels.map(x=>`[${x.status}] ${x.title}\n来源：${x.source} ${x.url}`).join('\n'):'本期没有带来源的市场线索，不能判断全网热度或明星代言。'}\n\n四、建议先做的事\n${top?'核对「'+top.name+'」的材料与交期，结合库存再决定是否补货。':'导入完整订单后再决定补货或调整商品。'}\n${m.unknownColor?'补齐 '+m.unknownColor+' 条明细的颜色，以免颜色偏好判断失真。':'继续保留款式、颜色与退款件数，便于后续比较。'}\n记录下一次内容发布或活动的时间，再观察后续订单变化。\n\n统计口径\n数据来自导入的订单明细；按下单日期归属。净销量扣除明确记录的退货件数；只有退款金额而未填退货件数时，不能准确扣减件数。仅已识别的支付、履约及退款状态计入，状态缺失或未识别的明细排除。比较期为紧邻本期的相同天数；没有记录不等于实际没有成交。`}
async function generate(kind){const [s,e]=C.reportRange(kind,today,start,end);const m=C.summarize(state.orders,s,e);if(!m.coverage)return toast('该时间范围没有已支付订单，请先导入对应数据');const r={id:uid(),title:(kind==='day'?'经营日报':kind==='week'?'经营周报':'经营报告')+' · '+s+' 至 '+e,created:stamp(),text:reportText(m),sample:demo};if(await change(()=>{state.reports.unshift(r);reportId=r.id;view='reports'}))toast('报告已保存')}
function login(){if(preview)return;modal('登录你的经营工作台','<p class="sub">使用启动服务时设置的管理员密码。</p><form id="loginForm"><div class="field"><label for="password">管理员密码</label><input id="password" type="password" autocomplete="current-password" required></div><button class="solid">进入工作台</button><p id="loginError" class="danger" role="status"></p></form>');$('#loginForm').onsubmit=async e=>{e.preventDefault();try{await api('login',{password:$('#password').value});auth=true;close();await load()}catch(err){$('#loginError').textContent=err.message}}}
async function load(){if(preview){let saved;try{saved=localStorage.getItem(storageKey);state=JSON.parse(saved||'null')||emptyState()}catch{state=emptyState()}realState=structuredClone(state);if(publicDemo&&!saved){state=sample();demo=true}render();return}try{const me=await api('me');auth=me.admin;if(!auth){render();login();return}const x=await api('business/state');state=x.state;version=x.version;realState=structuredClone(state);render();if($('#providerText'))$('#providerText').textContent=(me.provider==='local'?'本地模型模式：':'云端模型模式：')+me.model+'（连接将在分析时检查）'}catch(e){toast(e.message)}}
const field=(label,id,type='text',value='',required=true)=>`<div class="field"><label for="${id}">${label}</label><input id="${id}" type="${type}" value="${E(value)}" ${required?'required':''}></div>`;
function formModal(title,body,submit){modal(title,`<form id="editForm">${body}<button class="solid">保存</button><p class="danger" id="formError" role="status"></p></form>`);$('#editForm').onsubmit=async e=>{e.preventDefault();try{await submit();if(saveError)throw Error(saveError);close()}catch(err){$('#formError').textContent=err.message}}}
function addEvent(){formModal('记录经营事件',field('事件日期','eventDate','date',today)+field('事件名称','eventTitle')+`<div class="field"><label>事件类型</label><select id="eventType">${['内容发布','上新','活动','价格调整','缺货','其他'].map(x=>'<option>'+x+'</option>').join('')}</select></div><div class="field"><label for="eventNote">背景备注</label><textarea id="eventNote" maxlength="1000"></textarea></div>`,async()=>{const x={id:uid(),date:$('#eventDate').value,title:$('#eventTitle').value.trim(),type:$('#eventType').value,note:$('#eventNote').value};await change(()=>state.events.unshift(x))})}
function addIntel(id){const x=state.intel.find(x=>x.id===id)||{};formModal('保存一条趋势线索',field('标题','intelTitle','text',x.title||'')+field('来源名称','intelSource','text',x.source||'')+field('来源链接','intelUrl','url',x.url||'')+field('原文发布日期','intelDate','date',x.date||today)+`<div class="form-grid"><div class="field"><label>线索类型</label><select id="intelKind">${['新品','品牌合作','正式代言','个人同款','市场线索'].map(s=>`<option ${s===x.kind?'selected':''}>${s}</option>`).join('')}</select></div><div class="field"><label>核实状态</label><select id="intelStatus"><option ${x.status!=='已核实'?'selected':''}>待核实</option><option ${x.status==='已核实'?'selected':''}>已核实</option></select></div></div><div class="field"><label for="intelNote">依据及与品牌的关系</label><textarea id="intelNote" maxlength="2000">${E(x.note||'')}</textarea></div><p class="note">正式代言请以品牌或艺人官方公告核实；个人使用与活动亮相不自动等同代言。</p>`,async()=>{const n={id:x.id||uid(),title:$('#intelTitle').value.trim(),source:$('#intelSource').value.trim(),url:$('#intelUrl').value,date:$('#intelDate').value,kind:$('#intelKind').value,status:$('#intelStatus').value,note:$('#intelNote').value};if(!validUrl(n.url))throw Error('来源链接必须是HTTP或HTTPS地址');if(n.status==='已核实'&&!n.note.trim())throw Error('请补充核实依据');await change(()=>{const i=state.intel.findIndex(z=>z.id===n.id);if(i<0)state.intel.unshift(n);else state.intel[i]=n})})}
function addTask(){formModal('添加行动',field('行动内容','taskTitle')+field('截止日期（选填）','taskDue','date','',false),async()=>{const x={id:uid(),title:$('#taskTitle').value.trim(),due:$('#taskDue').value,done:false};await change(()=>state.tasks.unshift(x))})}
function addFeed(id){const old=state.feeds.find(f=>f.id===id);formModal(old?'编辑资讯来源':'添加 RSS / Atom 来源',field('来源名称','feedName','text',old?.name||'')+field('公开RSS地址（HTTPS）','feedUrl','url',old?.url||'')+'<p class="note">粘贴完整的RSS或Atom地址。首尾空格和反引号会自动清理，普通网页链接无法直接作为资讯源。</p>',async()=>{const url=$('#feedUrl').value.trim().replace(/^`+|`+$/g,'').trim();if(!url.startsWith('https://')||!validUrl(url))throw Error('请使用有效的HTTPS来源地址');if(state.feeds.some(f=>f.id!==old?.id&&f.url===url))throw Error('已添加同一来源地址');const f={id:old?.id||uid(),name:$('#feedName').value.trim(),url,lastFetch:old?.url===url?old.lastFetch:''};await change(()=>{const i=state.feeds.findIndex(x=>x.id===f.id);if(i<0)state.feeds.push(f);else state.feeds[i]=f})})}
async function fetchFeeds(){if(preview||demo)return toast('RSS获取需要本地服务，演示模式不会联网抓取');if(!state.feeds.length)return addFeed();let added=0,errors=[];toast('正在逐个获取来源…');for(const f of state.feeds){try{const x=await api('business/feeds',{url:f.url});await change(()=>{for(const item of x.items){if(state.intel.some(i=>i.url===item.url))continue;const parsed=new Date(item.published);state.intel.unshift({id:uid(),title:item.title,url:item.url,source:f.name,date:isNaN(parsed)?'':C.day(parsed),kind:'市场线索',status:'待核实',note:'来自RSS；需阅读原始来源核实。'+(!item.published?'原文未提供日期。':'原始时间：'+item.published)});added++}f.lastFetch=stamp()})}catch(e){errors.push(f.name+'：'+e.message)}}toast('新增 '+added+' 条线索'+(errors.length?'；部分来源失败':''));if(errors.length)modal('来源获取结果','<p>'+errors.map(E).join('<br>')+'</p>')}
function template(){download('莓莓兔订单模板.csv','\uFEFF订单号,明细编号,下单时间,商品名称,颜色,数量,实付金额,退款金额,退货件数,状态\nBB001,1,2026-11-23,示例商品,粉色,1,100.00,0,0,已支付\n','text/csv;charset=utf-8')}
const columns=[['orderId','订单号',true,['订单号','order_id']],['lineId','明细编号',false,['明细编号','子订单号','line_id']],['date','下单日期',true,['下单时间','下单日期','date']],['product','商品名称',true,['商品名称','商品名','product']],['color','颜色',false,['颜色','颜色规格','color']],['qty','数量',true,['数量','购买数量','quantity']],['paid','明细实付金额',true,['实付金额','明细实付金额','paid']],['refund','退款金额',false,['退款金额','refund']],['refundQty','退货件数',false,['退货件数','退款数量','refund_qty']],['status','订单状态',true,['状态','订单状态','status']]];
function openImport(){if(demo&&publicDemo){demo=false;state=structuredClone(realState);render()}if(demo)return toast('请先返回我的数据，再导入真实订单');modal('导入订单数据','<p class="sub">支持 UTF-8 编码的 CSV / TSV，可从 Excel 另存为 CSV。只导入经营分析字段，不需要客户姓名、电话或地址。</p><label class="file-drop">选择你的订单文件<input id="csvFile" type="file" accept=".csv,.tsv,text/csv,text/tab-separated-values"></label><p class="note">金额按商品明细填写；退款数量单独填写。重复订单号＋明细编号会更新原记录。</p><button class="soft" data-action="template">下载模板</button><p id="importError" class="danger" role="status"></p>');$('#csvFile').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>5_000_000)throw Error('文件不能超过5MB');mapImport(C.parseCSV(await file.text()))}catch(err){$('#importError').textContent=err.message}}}
function mapImport(raw){modal('核对订单字段',`<p class="sub">检测到 ${raw.rows.length} 行。请将文件列对应到分析字段。</p><form id="mappingForm"><div class="form-grid">${columns.map(([key,title,req,aliases])=>{const found=raw.headers.findIndex(h=>aliases.includes(h));return `<div class="field"><label for="map-${key}">${title}${req?' *':''}</label><select id="map-${key}" ${req?'required':''}><option value="">${req?'请选择':'不导入此字段'}</option>${raw.headers.map((h,i)=>`<option value="${i}" ${i===found?'selected':''}>${E(h)}</option>`).join('')}</select></div>`}).join('')}</div><button class="solid">预览并检查</button><p id="mappingError" class="danger" role="status"></p></form>`);$('#mappingForm').onsubmit=e=>{e.preventDefault();try{const mapping=Object.fromEntries(columns.map(([k])=>[k,$('#map-'+k).value]));const mapped=columns.map(([k])=>mapping[k]).filter(x=>x!=='');if(new Set(mapped).size!==mapped.length)throw Error('同一列不能重复映射到多个字段');const rows=C.normalize(raw,mapping);const seen=new Set;for(const r of rows){if(seen.has(r.id))throw Error('文件中出现重复订单明细，请填写唯一明细编号后重新导入');seen.add(r.id)}const existing=new Map(state.orders.map(o=>[o.id,o])),updates=rows.filter(r=>existing.has(r.id)).length;modal('确认导入',`<p class="sub">新增 ${rows.length-updates} 条，更新 ${updates} 条。导入后保存至你的工作台。</p><div class="data-preview"><table><thead><tr><th>商品</th><th>日期</th><th>数量</th><th>实付</th></tr></thead><tbody>${rows.slice(0,8).map(r=>`<tr><td>${E(r.product)} · ${E(r.color)}</td><td>${r.date}</td><td>${r.qty}</td><td>${money(r.paid)}</td></tr>`).join('')}</tbody></table></div><p class="note">${rows.filter(r=>!C.isPaidStatus(r.status)&&!['已取消','未付款','已关闭'].includes(r.status)).length} 条明细的状态待核对，已排除统计。已取消、未付款、已关闭也不计入。不含退货件数时默认0，可能高估净销量。${mapping.lineId===''?'未选明细编号：将使用订单号、商品和颜色组合识别同一明细。':''}</p><button id="confirmImport" class="solid">确认保存 ${rows.length} 条</button>`);$('#confirmImport').onclick=async()=>{if(await change(()=>{rows.forEach(r=>existing.set(r.id,r));state.orders=[...existing.values()];view='overview'})){close();toast('订单已导入')}}}catch(err){$('#mappingError').textContent=err.message}}}
function restore(){modal('恢复工作台备份','<p class="sub">从此工作台导出的 JSON 恢复，确认后替换当前订单、情报、事件、报告和待办。建议先导出当前备份。</p><input id="restoreFile" type="file" accept=".json"><p id="restoreError" class="danger"></p>');$('#restoreFile').onchange=async e=>{try{const f=e.target.files[0];if(f.size>8_000_000)throw Error('备份文件过大');const x=JSON.parse(await f.text());if(x.format!=='berrabai-owner-v1'||!x.state)throw Error('不是本工作台备份');for(const k of Object.keys(emptyState()))if(!Array.isArray(x.state[k]))throw Error('备份字段不完整');modal('确认恢复',`<p>将恢复 ${x.state.orders.length} 条订单、${x.state.intel.length} 条情报。当前数据将被替换。</p><button class="solid" id="confirmRestore">确认替换并恢复</button>`);$('#confirmRestore').onclick=async()=>{if(await change(()=>{state=x.state;reportId=''})){close();toast('备份已恢复')}}}catch(err){$('#restoreError').textContent=err.message}}}
async function ask(e){e.preventDefault();const q=$('#askInput').value.trim(),m=metrics();if(!m.coverage){$('#aiAnswer').textContent='这个时间范围尚无已支付订单，请先导入数据。';return}if(preview||demo){$('#aiAnswer').textContent='当前为规则报告预览，自由提问需要启动服务并连接模型。';return}$('#askButton').disabled=true;$('#aiAnswer').textContent='正在结合订单与经营背景分析…';try{const context=JSON.stringify({summary:m,events:state.events.filter(x=>x.date>=start&&x.date<=end),intel:state.intel.filter(x=>x.date>=start&&x.date<=end).slice(0,15)});const x=await api('business/analyze',{context,question:q});$('#aiAnswer').textContent=x.answer}catch(err){$('#aiAnswer').textContent=err.message}finally{if($('#askButton'))$('#askButton').disabled=false}}
const actions={'preview-report':()=>{$('#aiAnswer').textContent=reportText(metrics())},import:openImport,template,event:addEvent,task:addTask,'intel-new':()=>addIntel(''),feed:addFeed,'fetch-feeds':fetchFeeds,report:()=>generate('range'),print:()=>window.print(),'export-report':()=>{const r=state.reports.find(x=>x.id===reportId);if(r)download(r.title+'.txt',r.text)},backup:()=>download('莓莓兔经营备份-'+today+'.json',JSON.stringify({format:'berrabai-owner-v1',exported:stamp(),state},null,2),'application/json'),restore,range:()=>{try{const s=$('#rangeStart').value,e=$('#rangeEnd').value;C.summarize(state.orders,s,e);start=s;end=e;period=Math.round((new Date(e+'T12:00:00')-new Date(s+'T12:00:00'))/86400000)+1;render()}catch(e){toast(e.message)}},'model-help':()=>modal('本地模型启动方式','<p class="sub">安装 Ollama 后，在终端运行：</p><pre class="report">ollama pull qwen3:4b\nollama serve</pre><p class="sub">在另一个终端启动工作台：</p><pre class="report">export AI_PROVIDER=local\nexport LOCAL_MODEL=qwen3:4b\nexport ADMIN_PASSWORD=你设置的密码\npython3 server.py</pre><p class="note">模型未安装时不会伪造 AI 回答。纯统计与报告不依赖模型。</p>')};
$('#closeModal').onclick=close;
$('#demoButton').onclick=()=>{if(demo){demo=false;state=structuredClone(realState)}else{realState=structuredClone(state);state=sample();demo=true}reportId='';render()};$('#importButton').onclick=openImport;
$('#accountButton').onclick=()=>{if(preview)return modal('浏览器数据','<p>当前数据仅保存在此浏览器中。可在「资料与设置」导出备份；不会上传到品牌的私人数据库。</p>');if(!auth)return login();modal('管理员账号','<p>当前已登录自己的经营工作台。</p><button class="outline" id="logout">退出登录</button>');$('#logout').onclick=async()=>{await api('logout',{});auth=false;demo=false;state=realState=emptyState();close();render();login()}};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view){if(b.dataset.tab)productTab=b.dataset.tab;go(b.dataset.view)}else if(b.dataset.action)actions[b.dataset.action]?.();else if(b.dataset.period){period=Number(b.dataset.period);start=C.shift(today,1-period);end=today;render()}else if(b.dataset.tab){productTab=b.dataset.tab;render()}else if(b.dataset.generate)generate(b.dataset.generate);else if(b.dataset.report){reportId=b.dataset.report;render()}else if(b.dataset.intelEdit)addIntel(b.dataset.intelEdit);else if(b.dataset.feedEdit)addFeed(b.dataset.feedEdit)});
document.addEventListener('change',e=>{if(e.target.dataset.task)change(()=>{const x=state.tasks.find(x=>x.id===e.target.dataset.task);if(x)x.done=e.target.checked});if(e.target.id==='intelFilter'){intelFilter=e.target.value;render()}});
document.addEventListener('input',e=>{if(e.target.id==='productSearch'){search=e.target.value;const pos=e.target.selectionStart;render();$('#productSearch').focus();$('#productSearch').setSelectionRange(pos,pos)}});
document.addEventListener('submit',e=>{if(e.target.id==='askForm')ask(e)});
$('#dateLabel').textContent=new Date().toLocaleDateString('zh-CN',{year:'numeric',month:'long',day:'numeric',weekday:'long'});load();
})();
